using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "ChantingCustomTag", menuName = "Data/Battle/Battle Actions/Tags/ChantingCustomTag", order = 0)]
public class ChantingCustomTag : Tag
{
	[SerializeField]
	private ChantingEffect chantingEffect;

	[SerializeField]
	private ChantingAction chantingAction;

	public override string GetTagDescription()
	{
		LocalizationManager instance = ReferenceSingleton<LocalizationManager>.Instance;
		string text = Smart.Format(instance.GetLocalizedString("ExpressionWithDot"), Smart.Format(instance.GetLocalizedString("Purify_D"), chantingAction.GainChantingEffectAmount)) + "\n";
		string text2 = Smart.Format(instance.GetLocalizedAdditionalPurify(), 1, Smart.Format(instance.GetLocalizedEffectYouHave(), chantingEffect.GetEffectName())) + "\n";
		string text3 = chantingAction.GainChantingEffectAction.GetActionDescription(1) + "\n";
		return text + text2 + text3 + chantingEffect.IfYouDealPurifyNotChantingLoseLocalized;
	}
}
